   "type": "object",
   "properties": {
    "order_id": {
     "type": "string",
     "description": "The order id, such as '#W2378156'. It always begins with a '#'; pass it exactly as given, including that character."
    },
    "address1": {
     "type": "string",
     "description": "The first line of the address, such as '763 Broadway'."
    },
    "address2": {
     "type": "string",
     "description": "The second line of the address, such as 'Suite 135'. Pass an empty string if there is none."
    },
    "city": {
     "type": "string",
     "description": "The city, such as 'Philadelphia'."
