    },
    "address2": {
     "type": "string",
     "description": "The second line of the address, such as 'Suite 135'. Pass an empty string if there is none."
    },
    "city": {
     "type": "string",
     "description": "The city, such as 'Philadelphia'."
    },
    "state": {
     "type": "string",
     "description": "The two-letter state code, such as 'PA'."
    },
    "country": {
     "type": "string",
     "description": "The country, such as 'USA'."
    },
    "zip": {
     "type": "string",
     "description": "The zip code, such as '19122'."
    }
   },
   "required": [
    "user_id",
    "address1",
    "address2",
    "city",
    "state",
    "country",
    "zip"
   ]
  }
 }
]

